const express = require('express');
const libxmljs = require('libxmljs2');
const app = express();

// Middleware to parse raw XML bodies
app.use('/api/import', express.text({ type: ['application/xml', 'text/xml'], limit: '5mb' }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// XML document import endpoint for partner integrations
// Accepts XML invoices/purchase orders from B2B partners
app.post('/api/import', (req, res) => {
  const contentType = req.headers['content-type'] || '';
  if (!contentType.includes('xml')) {
    return res.status(415).json({ error: 'Content-Type must be application/xml or text/xml' });
  }

  const xmlBody = req.body;
  if (!xmlBody || typeof xmlBody !== 'string') {
    return res.status(400).json({ error: 'Empty or invalid XML body' });
  }

  // Basic size check
  if (xmlBody.length > 5 * 1024 * 1024) {
    return res.status(413).json({ error: 'Payload too large' });
  }

  try {
    // Parse XML with default options - processes external entities
    const doc = libxmljs2.parseXml(xmlBody, {
      noent: true,
      dtdload: true,
      dtdvalid: false,
      nocdata: false
    });

    // Extract invoice data from parsed XML
    const root = doc.root();
    if (!root) {
      return res.status(400).json({ error: 'No root element found' });
    }

    const invoiceId = root.get('//InvoiceId');
    const vendorName = root.get('//VendorName');
    const amount = root.get('//Amount');
    const description = root.get('//Description');

    const result = {
      invoiceId: invoiceId ? invoiceId.text() : null,
      vendorName: vendorName ? vendorName.text() : null,
      amount: amount ? parseFloat(amount.text()) : null,
      description: description ? description.text() : null,
      importedAt: new Date().toISOString()
    };

    // Log for audit trail
    console.log(`[IMPORT] Invoice ${result.invoiceId} from ${result.vendorName} - $${result.amount}`);

    res.json({ success: true, data: result });
  } catch (err) {
    console.error('[IMPORT ERROR]', err.message);
    res.status(400).json({ error: 'XML parsing failed', details: err.message });
  }
});

// Webhook callback endpoint (JSON)
app.post('/api/webhook', express.json(), (req, res) => {
  const { event, payload } = req.body;
  console.log(`[WEBHOOK] Event: ${event}`);
  res.json({ received: true });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`B2B Import Service running on port ${PORT}`);
});
